// Browser decryptor checks against the golden vectors (generated by an independent Python implementation and reproduced
// byte for byte by the .NET encryptor). Run: node --test web/watch/test/
import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { DecryptError, LinkError, SeekableLayout, base64UrlDecode, decryptMessage, parseFragment, parseHeader, recordNonce } from "../site/assets/ece.js";
import { EncryptedMedia, MissingError, validateMetadata } from "../site/assets/media.js";

const vectors = JSON.parse(readFileSync(fileURLToPath(new URL("./vectors.json", import.meta.url)), "utf8")).vectors;
const pattern = n => Uint8Array.from({ length: n }, (_, i) => (i * 7 + 3) % 251);
const hex = bytes => Buffer.from(bytes).toString("hex");
const sha256 = bytes => createHash("sha256").update(bytes).digest("hex");
const plaintextOf = v => v.plaintext === "pattern" ? pattern(v.plaintextLength) : Uint8Array.from(Buffer.from(v.plaintext, "hex"));
const withCipher = vectors.filter(v => v.ciphertext);

// A storage stand-in that honours single Range requests like R2 and counts what it sends.
function rangeServer(bytes, { ignoreRange = false, status } = {}) {
  const log = [];
  const fetchImpl = async (url, init = {}) => {
    const range = init.headers && init.headers.Range;
    log.push({ url, range, init });
    if (status) return new Response(null, { status });
    if (!range || ignoreRange) return new Response(bytes, { status: 200 });
    const [, from, to] = /^bytes=(\d+)-(\d+)$/.exec(range);
    const start = Number(from), end = Math.min(Number(to) + 1, bytes.length);
    return new Response(bytes.slice(start, end), { status: 206, headers: { "Content-Range": `bytes ${start}-${end - 1}/${bytes.length}` } });
  };
  return { fetchImpl, log };
}

test("vectors cover the RFC example, several records, an exact record boundary and an empty message", () => {
  assert.deepEqual(vectors.map(v => v.name).sort(), ["empty", "exact-boundary", "multi-record", "rfc8188-3.1", "three-default-records", "utf8-default-record-size"]);
});

for (const v of withCipher) {
  test(`decrypts golden vector ${v.name}`, async () => {
    const cipher = base64UrlDecode(v.ciphertext);
    assert.equal(sha256(cipher), v.ciphertextSha256);
    const plain = await decryptMessage(base64UrlDecode(v.key), cipher);
    assert.equal(hex(plain), hex(plaintextOf(v)));
    assert.equal(sha256(plain), v.plaintextSha256);
    const header = parseHeader(cipher);
    assert.equal(header.rs, v.rs);
    assert.equal(hex(header.salt), v.saltHex);
    assert.equal(new SeekableLayout(header, cipher.length).plainLength, v.plaintextLength);
  });
}

test("the wrong key is refused", async () => {
  const v = vectors.find(x => x.name === "multi-record");
  const wrong = base64UrlDecode(v.key); wrong[0] ^= 1;
  await assert.rejects(decryptMessage(wrong, base64UrlDecode(v.ciphertext)), DecryptError);
});

test("a changed byte, a dropped final record and swapped records are all refused", async () => {
  const v = vectors.find(x => x.name === "multi-record");
  const key = base64UrlDecode(v.key), cipher = base64UrlDecode(v.ciphertext);
  const flipped = cipher.slice(); flipped[100] ^= 0x40;
  await assert.rejects(decryptMessage(key, flipped), DecryptError);
  // Cut at a record boundary: the new last record still has delimiter 1, which marks it as not final.
  await assert.rejects(decryptMessage(key, cipher.slice(0, 21 + 64 * 6)), DecryptError);
  const swapped = cipher.slice(); swapped.set(cipher.subarray(21 + 64, 21 + 128), 21); swapped.set(cipher.subarray(21, 21 + 64), 21 + 64);
  await assert.rejects(decryptMessage(key, swapped), DecryptError);
});

test("a byte range is read by fetching only the records that hold it", async () => {
  const v = vectors.find(x => x.name === "multi-record");
  const cipher = base64UrlDecode(v.ciphertext), expected = pattern(v.plaintextLength);
  const server = rangeServer(cipher);
  const media = await EncryptedMedia.open("https://storage.test/w/x/media", base64UrlDecode(v.key), { fetchImpl: server.fetchImpl, expectedSize: 300 });
  assert.equal(media.size, 300);
  // The opening request asks for the header and the first record only.
  assert.equal(server.log[0].range, "bytes=0-65556");
  const before = server.log.length;
  // Bytes 150-160 lie in record 3 (47 plaintext bytes per 64-byte record): one request for exactly that record.
  assert.equal(hex(await media.read(150, 160)), hex(expected.subarray(150, 160)));
  assert.deepEqual(server.log.slice(before).map(r => r.range), [`bytes=${21 + 3 * 64}-${21 + 4 * 64 - 1}`]);
  // A cached record is not fetched again; a range across records 3-5 fetches only 4 and 5.
  assert.equal(hex(await media.read(141, 260)), hex(expected.subarray(141, 260)));
  assert.deepEqual(server.log.slice(before + 1).map(r => r.range), [`bytes=${21 + 4 * 64}-${21 + 6 * 64 - 1}`]);
  for (const [start, end] of [[0, 300], [299, 300], [46, 48], [282, 300], [0, 1]]) assert.equal(hex(await media.read(start, end)), hex(expected.subarray(start, end)));
  // Requests carry no cookies and no referrer; nothing but the path and the range reaches storage.
  for (const entry of server.log) { assert.equal(entry.init.credentials, "omit"); assert.equal(entry.init.referrerPolicy, "no-referrer"); }
});

test("storage that ignores Range still works, and a missing object reads as expired", async () => {
  const v = vectors.find(x => x.name === "exact-boundary");
  const server = rangeServer(base64UrlDecode(v.ciphertext), { ignoreRange: true });
  const media = await EncryptedMedia.open("https://storage.test/m", base64UrlDecode(v.key), { fetchImpl: server.fetchImpl });
  assert.equal(hex(await media.read(0, 94)), hex(pattern(94)));
  assert.equal(server.log.length, 1);
  await assert.rejects(EncryptedMedia.open("https://storage.test/m", base64UrlDecode(v.key), { fetchImpl: rangeServer(new Uint8Array(0), { status: 404 }).fetchImpl }), MissingError);
});

test("seekable reads refuse a media object cut at a record boundary", async () => {
  const v = vectors.find(x => x.name === "multi-record");
  const cut = base64UrlDecode(v.ciphertext).slice(0, 21 + 64 * 6);
  const media = await EncryptedMedia.open("https://storage.test/m", base64UrlDecode(v.key), { fetchImpl: rangeServer(cut).fetchImpl });
  await assert.rejects(media.read(240, 250), DecryptError);
});

test("record nonces match a 64-bit big-endian XOR", () => {
  const base = Uint8Array.from({ length: 12 }, (_, i) => 0xf0 + i);
  for (const sequence of [0, 1, 255, 65536, 2 ** 32 - 1, 2 ** 32, 2 ** 40 + 5]) {
    const expected = base.slice();
    const view = new DataView(expected.buffer);
    view.setBigUint64(4, view.getBigUint64(4) ^ BigInt(sequence));
    assert.equal(hex(recordNonce(base, sequence)), hex(expected));
  }
});

test("link fragments must be an id and a 16-byte key", () => {
  const ok = parseFragment("#AAAAAAAAAAAAAAAAAAAAAA.AAECAwQFBgcICQoLDA0ODw");
  assert.equal(ok.id, "AAAAAAAAAAAAAAAAAAAAAA");
  assert.equal(hex(ok.key), "000102030405060708090a0b0c0d0e0f");
  for (const bad of ["", "#", "#abc", "#AAAAAAAAAAAAAAAAAAAAAA", "#AAAAAAAAAAAAAAAAAAAAAA.AAECAwQFBgcICQoLDA0OD", "#AAAAAAAAAAAAAAAAAAAAAA.AAECAwQFBgcICQoLDA0OD+", "#AAAAAAAAAAAAAAAAAAAAAA.AAECAwQFBgcICQoLDA0ODw.x"])
    assert.throws(() => parseFragment(bad), LinkError);
});

test("metadata must describe a consistent fragment index", () => {
  const good = { v: 1, name: "a.mp4", kind: "video", mime: "video/mp4", size: 1000, end: 990, init: 100, duration: 4, frags: [[0, 100], [2, 500]] };
  validateMetadata(good);
  for (const bad of [{ ...good, v: 2 }, { ...good, frags: [] }, { ...good, frags: [[0, 100], [1, 50]] }, { ...good, frags: [[2, 100], [0, 500]] }, { ...good, end: 2000 }, { ...good, init: 0 }])
    assert.throws(() => validateMetadata(bad), DecryptError);
});
